def _reference(blocks):
    lab = np.concatenate([b['lab_id'] for b in blocks])
    refs = np.concatenate([b['ref_coupons'] for b in blocks])
    stats = {}
    for key in np.unique(lab):
        r = refs[lab == key]
        stats[key] = (np.median(r.mean(axis=0)), np.median(r.std(axis=0)))
    return stats

def _standardize(block, reference, fill=None):
    lab = block['lab_id']
    x = np.array(block['coupon_features_raw'], dtype=float, copy=True)
    for key in np.unique(lab):
        (loc, scale) = reference[key]
        x[lab == key] = (x[lab == key] - loc) / (scale if scale > 0 else 1.0)
    valid = np.isfinite(x)
    if fill is None:
        (_, group, counts) = np.unique(np.column_stack((lab, block['stratum'])), axis=0, return_inverse=True, return_counts=True)
        w = 1.0 / counts[group, None]
        denom = (w * valid).sum(axis=0)
        fill = np.divide((w * np.where(valid, x, 0)).sum(axis=0), denom, out=np.zeros(x.shape[1]), where=denom > 0)
    return (np.column_stack((np.ones(len(lab)), np.where(valid, x, fill))), fill)

def _bridge(cal):
    raw = cal['bridge_raw']
    return np.linalg.lstsq(np.column_stack((raw, np.ones(len(raw)))), cal['true_channel_loads'], rcond=None)[0].sum(axis=1)
